import sys
input = sys.stdin.read
data = input().split()

Q = int(data[0])
queries = [list(map(int, data[i:i+2])) for i in range(1, 2*Q+1)]

def count_powerful_numbers(L, R):
    count = 0
    limit = int(R ** 0.5) + 1
    for i in range(1, limit):
        for j in range(2, 64):
            num = i ** j
            if num >= L and num <= R:
                count += 1
            if num > R:
                break
    return count

results = [count_powerful_numbers(L, R) for L, R in queries]

for result in results:
    print(result)

